-- Step 141. Bachelors scholarships for international students at Australian and US schools in the database.
-- SOURCE: web-search results (ChatGPT, 1 Nov 2026). These pages could not be opened from here, so NOTHING below is confirmed.
-- Each row starts with "NOT YET CHECKED" in its requirements text and has verified = false.
-- Left out: masters-only awards, awards that exclude Ghana, Australia Awards (masters only), and Wisconsin-Madison and Michigan State (already loaded and checked in step140).
-- Safe to run more than once: a row is added only if that school does not already have an award of that name.
insert into public.scholarships (name, funder, country, funding_type, level, criteria, award_note, link, source_url, school_id, verified, demo)
select v.name, s.name, s.country, v.ftype, v.lvl, v.criteria, v.award, v.url, v.url, s.id, false, false
