join public.schools s on s.name = v.school
where not exists (select 1 from public.scholarships x where x.school_id = s.id and x.name = v.name);

-- Check: rows added per school.
select s.name school, count(*) awards from public.scholarships c join public.schools s on s.id = c.school_id group by 1 order by 2 desc, 1;
